    def hypotheses(self, request: CreateSourcingRun) -> list[SearchHypothesis]:
        return self.hypotheses_from_draft(self.draft(request))

    def hypotheses_from_draft(self, draft: PlanningDraft) -> list[SearchHypothesis]:
