.context-switch button{display:flex;align-items:center;gap:6px;border:0;border-bottom:2px solid transparent;background:transparent;color:var(--quiet);padding:0 2px;font-size:11px}
.context-switch button[aria-pressed=true]{color:var(--accent);border-bottom-color:var(--accent)}
.context-switch button:hover:not(:disabled){color:var(--text)}
.recording-context .explorer-panel{height:auto;min-height:0;flex:1}
.robot-panel{display:flex;flex-direction:column;min-height:0;flex:1;background:#161d21}
