import { useEffect, useRef, useState } from 'react';
import { Plus, SearchCheck, X } from 'lucide-react';
import { sourcingIsActive, type RequirementsPreview, type Services, type SourcingReview, type SourcingRun } from '../services';
import RequirementEditor, { selectedRequirements, type RequirementPriorities } from './RequirementEditor';
import ScoutReview from './ScoutReview';

const demoBrief = 'Find 1 kHz robot collision and intentional contact time-series torque data from https://github.com/zhang-zengjie/robot-raw-collision-signals';
const errorText = (error: unknown) => error instanceof Error ? error.message : 'The request failed.';
type Intent = { signature: string; key: string };

export default function DatasetScout({ services, onUseSource }: { services: Services; onUseSource: (url: string) => void }) {
  const [brief, setBrief] = useState(demoBrief);
  const [resumeId, setResumeId] = useState('');
  const [runId, setRunId] = useState('');
  const [pollRevision, setPollRevision] = useState(0);
  const [run, setRun] = useState<SourcingRun | null>(null);
  const [busy, setBusy] = useState('');
  const [error, setError] = useState('');
  const [sourceReady, setSourceReady] = useState(false);
  const [customRequirement, setCustomRequirement] = useState('');
  const [customRequirements, setCustomRequirements] = useState<string[]>([]);
  const [preview, setPreview] = useState<RequirementsPreview | null>(null);
  const [priorities, setPriorities] = useState<RequirementPriorities>({});
  const intent = useRef<Intent | null>(null);

  useEffect(() => {
    if (!runId || !services.connected) return;
    let alive = true;
    let timer: ReturnType<typeof setTimeout> | undefined;
    const poll = async () => {
      try {
        const next = await services.getSourcingRun(runId);
        if (!alive) return;
        setRun(next); setError('');
        if (sourcingIsActive(next.status)) timer = setTimeout(poll, 1500);
      } catch (reason) { if (alive) setError(`Could not load sourcing run: ${errorText(reason)}`); }
    };
    void poll();
    return () => { alive = false; clearTimeout(timer); };
  }, [services, runId, pollRevision]);

  function invalidatePreview() {
    setPreview(null); setPriorities({}); intent.current = null;
  }

  async function previewRequirements() {
    const normalized = brief.trim();
    if (normalized.length < 20) { setError('Describe the dataset need in at least 20 characters.'); return; }
    setBusy('preview'); setError('');
    try {
      const next = await services.previewSourcingRequirements({
        brief: normalized, customRequirements,
      });
      setPreview(next);
      setPriorities(Object.fromEntries(next.requirements.map(item => [item.id, item.priority])));
    } catch (reason) { setError(`Could not preview requirements: ${errorText(reason)}`); }
    finally { setBusy(''); }
  }

  function addCustomRequirement() {
    const normalized = customRequirement.trim();
    if (normalized.length < 3 || customRequirements.includes(normalized)) return;
    setCustomRequirements(items => [...items, normalized]);
    setCustomRequirement(''); invalidatePreview();
  }

  async function start() {
    const normalized = brief.trim();
    if (!preview) { setError('Review the research requirements before starting.'); return; }
    const request = {
      brief: normalized,
      requirements: selectedRequirements(preview.requirements, priorities),
    };
    const signature = JSON.stringify(request);
    setBusy('start'); setError(''); setRun(null); setSourceReady(false);
    try {
      if (!intent.current || intent.current.signature !== signature) intent.current = { signature, key: crypto.randomUUID() };
      const accepted = await services.startSourcingRun(request, intent.current.key);
      intent.current = null;
      setRunId(accepted.runId); setResumeId(accepted.runId); setPollRevision(value => value + 1);
    } catch (reason) { setError(`Could not start evidence review: ${errorText(reason)}`); }
    finally { setBusy(''); }
  }

  async function review(reviewRequest: SourcingReview) {
    if (!run) return;
    setBusy(reviewRequest.decision); setError('');
    try {
      const next = await services.reviewSourcingRun(run.runId, reviewRequest);
      if (reviewRequest.decision === 'APPROVE') next.manifest = await services.getSourcingManifest(run.runId);
      setRun(next);
    } catch (reason) { setError(`Could not apply reviewer decision: ${errorText(reason)}`); }
    finally { setBusy(''); }
  }

  return <section className="workspace-section dataset-scout" aria-labelledby="scout-title">
    <div className="section-heading"><div><p className="eyebrow">Agentic sourcing</p><h2 id="scout-title">Evidence-complete dataset scout</h2><p>Search bounded hypotheses, verify native sources, and review a deterministic recommendation before ingestion.</p></div><SearchCheck size={20} aria-hidden="true" /></div>
    {!services.connected && <p className="status-note">Configure the team API to run or resume dataset research.</p>}
    <label htmlFor="sourcing-brief">Research brief</label>
    <textarea id="sourcing-brief" rows={3} value={brief} onChange={event => { setBrief(event.target.value); invalidatePreview(); }} disabled={!services.connected || Boolean(busy)} />
    <form className="custom-requirement" onSubmit={event => { event.preventDefault(); addCustomRequirement(); }}>
      <label htmlFor="custom-sourcing-requirement">Custom mandatory requirement</label>
      <div><input id="custom-sourcing-requirement" value={customRequirement} onChange={event => setCustomRequirement(event.target.value)} maxLength={500} placeholder="Example: At least 200 labelled collision sequences" disabled={!services.connected || Boolean(busy)} /><button className="btn" disabled={customRequirement.trim().length < 3 || Boolean(busy)}><Plus size={14} aria-hidden="true" />Add</button></div>
    </form>
    {customRequirements.length > 0 && <ul className="custom-requirements" aria-label="Custom requirements">{customRequirements.map(item => <li key={item}><span>{item}</span><button type="button" aria-label={`Remove custom requirement: ${item}`} onClick={() => { setCustomRequirements(values => values.filter(value => value !== item)); invalidatePreview(); }}><X size={13} aria-hidden="true" /></button></li>)}</ul>}
    {preview && <RequirementEditor requirements={preview.requirements} priorities={priorities} onPriorityChange={(id, priority) => { setPriorities(current => ({ ...current, [id]: priority })); intent.current = null; }} />}
    <div className="scout-actions">
      {preview
        ? <button className="btn btn-primary" type="button" disabled={!services.connected || Boolean(busy)} onClick={() => void start()}><SearchCheck size={15} aria-hidden="true" />{busy === 'start' ? 'Starting…' : 'Start evidence review'}</button>
        : <button className="btn btn-primary" type="button" disabled={!services.connected || Boolean(busy)} onClick={() => void previewRequirements()}><SearchCheck size={15} aria-hidden="true" />{busy === 'preview' ? 'Preparing…' : 'Review requirements'}</button>}
      <form onSubmit={event => { event.preventDefault(); setError(''); setRun(null); setSourceReady(false); setRunId(resumeId.trim()); setPollRevision(value => value + 1); }}><label htmlFor="sourcing-run-id">Resume run</label><input id="sourcing-run-id" value={resumeId} onChange={event => setResumeId(event.target.value)} placeholder="Run ID" disabled={!services.connected || Boolean(busy)} /><button className="btn" disabled={!services.connected || !resumeId.trim() || Boolean(busy)}>Load</button></form>
    </div>
    {error && <p className="error-message" role="alert">{error}</p>}
    {run ? <ScoutReview run={run} busy={busy} onReview={reviewRequest => void review(reviewRequest)} onUseSource={url => { onUseSource(url); setSourceReady(true); }} /> : runId && !error ? <p className="status-note" aria-live="polite">Loading sourcing run…</p> : null}
    {sourceReady && <p className="status-note" role="status">Source URL added to the ingestion form below. Review it before starting ingestion.</p>}
  </section>;
}
import type { RequirementDefinition, RequirementPriority } from '../services';

export type RequirementChoice = RequirementPriority | 'DISABLED';
export type RequirementPriorities = Record<string, RequirementChoice>;

export function selectedRequirements(
  requirements: RequirementDefinition[],
  priorities: RequirementPriorities,
) {
  return requirements.flatMap(requirement => {
    const priority = requirement.isSystemRequired ? 'MUST' : priorities[requirement.id];
    return priority && priority !== 'DISABLED' ? [{ ...requirement, priority }] : [];
  });
}

export default function RequirementEditor({
  requirements,
  priorities,
  onPriorityChange,
}: {
  requirements: RequirementDefinition[];
  priorities: RequirementPriorities;
  onPriorityChange: (id: string, priority: RequirementChoice) => void;
}) {
  return <section className="requirement-editor" aria-labelledby="research-contract-title">
    <div>
      <p className="eyebrow">Preflight</p>
      <h3 id="research-contract-title">Research contract</h3>
      <p>Mandatory requirements reject candidates. Preferred requirements guide ranking only.</p>
    </div>
    <div className="requirement-list">{requirements.map(requirement =>
      <div className="requirement-row" key={requirement.id}>
        <div>
          <strong>{requirement.label}</strong>
          <span>{requirement.category === 'OTHER' ? 'Custom' : requirement.category.replaceAll('_', ' ').toLowerCase()}</span>
          <small>{requirement.description}</small>
        </div>
        {requirement.isSystemRequired
          ? <span className="requirement-fixed">Always required</span>
          : <label>
            <span>Priority for {requirement.label}</span>
            <select
              value={priorities[requirement.id] ?? requirement.priority}
              onChange={event => onPriorityChange(requirement.id, event.target.value as RequirementChoice)}
            >
              <option value="MUST">Must have</option>
              <option value="SHOULD">Preferred</option>
              <option value="DISABLED">Disabled</option>
            </select>
          </label>}
      </div>,
    )}</div>
  </section>;
}
export type SourcingStatus =
  | 'QUEUED' | 'PLANNING' | 'DISCOVERING' | 'VERIFYING' | 'ASSESSING'
  | 'AWAITING_APPROVAL' | 'APPROVED' | 'REJECTED' | 'NEEDS_INPUT' | 'FAILED';

export type SourcingConstraints = {
  mustHave: string[];
  preferred: string[];
  allowedLicenses: string[];
  maxDownloadBytes: number;
};

export type RequirementPriority = 'MUST' | 'SHOULD';
export type RequirementCategory = 'DOMAIN' | 'TASK_LABELS' | 'SAMPLING_RATE' | 'MODALITY'
  | 'LICENSE' | 'PROVENANCE' | 'SCHEMA' | 'ACQUISITION' | 'OTHER';

export type RequirementDefinition = {
  id: string;
  label: string;
  description: string;
  priority: RequirementPriority;
  category: RequirementCategory;
  expectedValues: string[];
  isSystemRequired?: boolean;
};

export type CreateSourcingRun = {
  brief: string;
  constraints?: Partial<SourcingConstraints>;
  requirements?: RequirementDefinition[];
};

export type RequirementPreviewRequest = {
  brief: string;
  constraints?: Partial<SourcingConstraints>;
  customRequirements: string[];
};

export type RequirementsPreview = { requirements: RequirementDefinition[] };

export type ResearchRequirement = RequirementDefinition & {
  status: 'VERIFIED' | 'MISSING' | 'CONFLICTING' | 'UNVERIFIED';
  evidenceIds: string[];
};

export type DatasetCandidate = {
  id: string;
  name: string;
  canonicalUrl: string;
  sourceKind: 'ZENODO' | 'GITHUB' | 'HUGGING_FACE';
  description: string;
  revision: string | null;
  relatedUrls: string[];
  sourceRole?: 'DISCOVERY_LEAD' | 'DATASET_ARTIFACT';
  discoveryDepth?: number;
  discoveredFromCandidateId?: string | null;
};

export type DatasetProfile = {
  candidateId: string;
  name: string;
  canonicalUrl: string;
  sourceKinds: ('ZENODO' | 'GITHUB' | 'HUGGING_FACE')[];
  revision: string | null;
  licenseId: string | null;
  fileCount: number | null;
  totalSizeBytes: number | null;
  fileExtensions: string[];
  domains: string[];
  labels: string[];
  sampleRateHz: number | null;
  channelCount: number | null;
  hasTimeSeriesFiles: boolean;
  schemaDocumented: boolean;
  acquisitionFeasible: boolean;
  isDatasetArtifact?: boolean;
  datasetIdentityReason?: string;
};

export type EvidenceRecord = {
  id: string;
  candidateId: string;
  requirementId: string | null;
  claimKey: string;
  observedValue: string;
  sourceUrl: string;
  sourceKind: 'ZENODO' | 'GITHUB' | 'HUGGING_FACE';
  status: 'VERIFIED' | 'MISSING' | 'CONFLICTING' | 'UNVERIFIED';
  precedence: number;
  retrievedAt: string;
  note: string | null;
};

export type CandidateAssessment = {
  candidateId: string;
  gates: { gate: string; passed: boolean; reason: string; evidenceIds: string[] }[];
  score: {
    taskFit: number;
    trainingReadiness: number;
    acquisitionIntegrity: number;
    provenanceDocumentation: number;
    integrationReadiness: number;
    licenseClarity: number;
    evidenceConsistency: number;
  };
  totalScore: number;
  tier: 'RECOMMEND' | 'SHORTLIST' | 'REJECT';
  evidenceConfidence: 'HIGH' | 'MEDIUM' | 'LOW';
  recommendationConfidence: 'HIGH' | 'MEDIUM' | 'LOW';
  missingRequirementIds: string[];
  conflicts: string[];
};

export type SourcingManifest = {
  runId: string;
  candidateId: string;
  name: string;
  canonicalUrl: string;
  revision: string | null;
  licenseId: string;
  labels: string[];
  sampleRateHz: number | null;
  fileExtensions: string[];
  totalSizeBytes: number | null;
  evidenceIds: string[];
  limitations: string[];
  approvedAt: string;
};

export type SourcingReview =
  | { decision: 'APPROVE'; candidateId: string; note?: string }
  | { decision: 'REJECT'; candidateId?: string; note: string };

export type RefinementOutcome = {
  iteration: number;
  feedback: string;
  query: string;
  outcome: 'RECOMMENDATION_CHANGED' | 'RECOMMENDATION_WITHHELD' | 'EVIDENCE_EXPANDED' | 'CANDIDATES_ADDED' | 'NO_CHANGE';
  rejectedCandidateId: string | null;
  previousRecommendedCandidateId: string | null;
  recommendedCandidateId: string | null;
  newCandidateIds: string[];
  newEvidenceIds: string[];
};

export type SourcingRun = {
  runId: string;
  status: SourcingStatus;
  brief: string;
  constraints: SourcingConstraints;
  requirements: ResearchRequirement[];
  requirementsConfirmed?: boolean;
  hypotheses: { id: string; rationale: string; query: string; status: 'PLANNED' | 'SEARCHED' | 'EXHAUSTED'; isGapQuery: boolean }[];
  candidates: DatasetCandidate[];
  profiles: DatasetProfile[];
  evidence: EvidenceRecord[];
  assessments: CandidateAssessment[];
  recommendedCandidateId: string | null;
  approvedCandidateId: string | null;
  excludedCandidateIds: string[];
